using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using TMPro;using UnityEngine.TextCore.LowLevel;
public static class PrepareJapaneseFont{
 public static object Run(){AssetDatabase.Refresh();const string path="Assets/BokumyakuPrototype/Resources/BokumyakuFonts/NotoSerifCJKjp-Regular.otf";var importer=(TrueTypeFontImporter)AssetImporter.GetAtPath(path);importer.includeFontData=true;importer.SaveAndReimport();var source=AssetDatabase.LoadAssetAtPath<Font>(path);var chars=new System.Collections.Generic.HashSet<char>();for(char c=' ';c<127;c++)chars.Add(c);foreach(var file in Directory.GetFiles("Assets/BokumyakuPrototype","*.cs",SearchOption.AllDirectories))foreach(char c in File.ReadAllText(file))if(c>=160&&!char.IsSurrogate(c))chars.Add(c);var font=TMP_FontAsset.CreateFontAsset(source,48,5,GlyphRenderMode.SDFAA,2048,2048,AtlasPopulationMode.Dynamic);font.name="Bokumyaku Japanese";font.isMultiAtlasTexturesEnabled=true;string missing;font.TryAddCharacters(new string(chars.ToArray()),out missing);font.atlasPopulationMode=AtlasPopulationMode.Static;const string target="Assets/BokumyakuPrototype/Resources/BokumyakuFonts/BattleJapanese.asset";if(AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(target)!=null)throw new Exception("Font asset already exists");AssetDatabase.CreateAsset(font,target);foreach(var tex in font.atlasTextures)AssetDatabase.AddObjectToAsset(tex,font);AssetDatabase.AddObjectToAsset(font.material,font);EditorUtility.SetDirty(font);AssetDatabase.SaveAssets();return new{characters=chars.Count,missing,atlases=font.atlasTextures.Length};}}
